def get_tbabs(nh):
    """
    Get an interpolator for photoelectric absorption
    # Arguments
    * nh: hydrogen column density in 1e22 cm^-2
    # Returns
    * An interpolator for energy in units of keV, that spits out the multiplier
    """
    e_centers = np.array(ENERGIES)
    e_centers = (e_centers[1:] + e_centers[:-1]) / 2
    interpolator = interp1d(e_centers, np.array(TBABS)**nh)

    def output(energies):
        out = np.zeros(len(energies))
        out[energies < ENERGIES[0]] = 0
        out[energies > ENERGIES[-1]] = 1
        middling = (energies > ENERGIES[0]) & (energies < ENERGIES[-1])
        out[middling] = interpolator(energies[middling])
        return out
    return output

if __name__ == "__main__":
    import matplotlib.pyplot as plt
    plt.style.use("root")

    tbabs = get_tbabs(1)
    energies = np.linspace(1, 10, 200)
    fig, ax = plt.subplots()
    ax.plot(energies, tbabs(energies))
    ax.set_xlabel("Energy [keV]")
    ax.set_ylabel("Absorption")
    ax.set_xscale("log")
    ax.set_yscale("log")
    fig.savefig("figs/tbabs.png")